  "status.database": "ಕೇಸ್ ಸಂಗ್ರಹಣೆ",
  "status.ai": "AI",
  "status.voice": "ಧ್ವನಿ",
  "status.email": "ಇಮೇಲ್",
  "footer.built": "ಬಿಲ್ಡ್ ವಾಟ್ ಮೂವ್ಸ್ ಇಂಡಿಯಾ ಹ್ಯಾಕಥಾನ್‌ಗಾಗಿ ನಿರ್ಮಿಸಲಾಗಿದೆ. ಯಾವುದೇ ಸರ್ಕಾರಿ ಸಂಸ್ಥೆಯೊಂದಿಗೆ ಸಂಬಂಧ, ಅನುಮೋದನೆ ಅಥವಾ ನಂಟು ಇಲ್ಲ. ಎಲ್ಲ ಉಲ್ಲೇಖ ಸಂಖ್ಯೆಗಳೂ ಅಣಕು.",
  "start.h1": "ಏನಾಯಿತೆಂದು ಹೇಳಿ.",
  "start.sub": "ನಿಮ್ಮ ಸ್ವಂತ ಮಾತುಗಳಲ್ಲಿ, ನೀವು ನಂಬುವ ವ್ಯಕ್ತಿಗೆ ವಿವರಿಸುವಂತೆ. ನಾವು ಪರಿಶೀಲಿಸಲು ನಿಮಗೆ ರಚನಾತ್ಮಕ ಡ್ರಾಫ್ಟ್ ಅನ್ನು ಸೂಚಿಸುತ್ತೇವೆ.",
  "start.mic": "ಮಾತನಾಡಲು ಒತ್ತಿ ಹಿಡಿಯಿರಿ",
  "start.micStop": "ಕೇಳುತ್ತಿದ್ದೇವೆ — ಮುಗಿದ ಮೇಲೆ ಬಿಡಿ",
  "start.micHint": "ನೀವು ಮಾತನಾಡುತ್ತಿರುವುದು",
  "start.voiceDisclosure": "ಧ್ವನಿಯು ನಿಮ್ಮ ಮೈಕ್ರೊಫೋನ್ ಅನ್ನು ಬಳಸುತ್ತದೆ. ಬ್ರೌಸರ್ ಭಾಷಣ ಗುರುತಿಸುವಿಕೆಯನ್ನು ನಿಮ್ಮ ಬ್ರೌಸರ್ ಮಾರಾಟಗಾರರ ಭಾಷಣ ಸೇವೆಯಿಂದ ಪ್ರಕ್ರಿಯೆಗೊಳಿಸಬಹುದು; ರೆಕಾರ್ಡ್ ಮಾಡಿದ ಆಡಿಯೋ ಮೋಡ್ ರೆಕಾರ್ಡಿಂಗ್ ಅನ್ನು Kavach ನ ಕಾನ್ಫಿಗರ್ ಮಾಡಿದ ಲಿಪ್ಯಂತರ ಒದಗಿಸುವವರಿಗೆ ಕಳುಹಿಸುತ್ತದೆ. ಆಡಿಯೋ ಬೈಟ್‌ಗಳನ್ನು ನಿಮ್ಮ ಕೇಸ್ ಫೈಲ್‌ಗೆ ಸೇರಿಸಲಾಗುವುದಿಲ್ಲ, ಆದರೆ ಪ್ರತಿ ಸೇವೆಯ ಡೇಟಾ ನಿರ್ವಹಣೆಯು ಅನ್ವಯಿಸಬಹುದು. ಧ್ವನಿ ಪ್ರಕ್ರಿಯೆಯನ್ನು ತಪ್ಪಿಸಲು ಬದಲಿಗೆ ಟೈಪ್ ಮಾಡಿ.",
  "start.voiceConsent": "ಈ ಹೇಳಿಕೆಗಾಗಿ ಮೈಕ್ರೊಫೋನ್ ಪ್ರವೇಶ ಮತ್ತು ಧ್ವನಿ ಲಿಪ್ಯಂತರವನ್ನು ನಾನು ಅರ್ಥಮಾಡಿಕೊಂಡಿದ್ದೇನೆ ಮತ್ತು ಸಮ್ಮತಿಸುತ್ತೇನೆ.",
  "start.or": "ಅಥವಾ ಬರೆಯಿರಿ",
  "start.placeholder": "ಉದಾಹರಣೆಗೆ: ನಿನ್ನೆ ಸಂಜೆ ಯಾರೋ ಕರೆ ಮಾಡಿ ತಾನು ಬ್ಯಾಂಕಿನಿಂದ ಮಾತನಾಡುತ್ತಿದ್ದೇನೆ ಎಂದರು, ಕಾರ್ಡ್ ಬ್ಲಾಕ್ ಆಗಿದೆ ಎಂದರು, ಒಟಿಪಿ ಕೇಳಿದರು, ಮತ್ತು ಮೂರು ವಹಿವಾಟುಗಳಲ್ಲಿ ಎಂಬತ್ತೈದು ಸಾವಿರ ರೂಪಾಯಿ ಹೋಯಿತು.",
  "start.examples": "ಎಲ್ಲಿಂದ ಆರಂಭಿಸಬೇಕೆಂದು ತಿಳಿಯುತ್ತಿಲ್ಲವೇ? ಇವುಗಳಲ್ಲಿ ಒಂದನ್ನು ನೋಡಿ",
  "start.ex1": "ಯಾರೋ ಬ್ಯಾಂಕಿನವರಂತೆ ನಟಿಸಿ ಕರೆ ಮಾಡಿ ಒಟಿಪಿ ಪಡೆದರು",
  "start.ex2": "ನಾನು ಒಂದು ಜಾಲತಾಣದಲ್ಲಿ ಫೋನಿಗೆ ಹಣ ಕೊಟ್ಟೆ, ವಸ್ತು ಎಂದೂ ಬರಲಿಲ್ಲ",
  "start.ex3": "ವಿಡಿಯೊ ಕರೆಯಲ್ಲಿ ಪೊಲೀಸ್ ಎಂದು ಹೇಳಿ ನಾನು ಡಿಜಿಟಲ್ ಬಂಧನದಲ್ಲಿದ್ದೇನೆ ಎಂದರು",
  "start.ex4": "ಯಾರೋ ನನ್ನ ಫೋಟೋಗಳಿಂದ ನಕಲಿ ಇನ್‌ಸ್ಟಾಗ್ರಾಂ ಖಾತೆ ಮಾಡಿದ್ದಾರೆ",
  "start.ex5": "ವಾಟ್ಸ್‌ಆ್ಯಪ್‌ನ ಹೂಡಿಕೆ ಗುಂಪು ಹಣ ಪಡೆದು ಮಾಯವಾಯಿತು",
  "start.submit": "ಮುಂದುವರಿಯಿರಿ",
  "start.analysing": "ನೀವು ಬರೆದದ್ದನ್ನು ಓದುತ್ತಿದ್ದೇವೆ",
  "start.analysing2": "ಅಧಿಕೃತ ವರ್ಗಗಳಿಗೆ ಹೊಂದಿಸುತ್ತಿದ್ದೇವೆ",
  "start.analysing3": "ನಿಮ್ಮ ಉತ್ತರಗಳಿಗೆ ಹೊಂದುವ ಕ್ರಮಗಳನ್ನು ಸಿದ್ಧಪಡಿಸಲಾಗುತ್ತಿದೆ",
  "start.privacy": "ನಿಮ್ಮ ಆಧಾರ್ ಸಂಖ್ಯೆ, ಪ್ಯಾನ್, ಕಾರ್ಡ್ ಪಿನ್, ಪಾಸ್‌ವರ್ಡ್ ಅಥವಾ ಯಾವುದೇ ಒಟಿಪಿ ಬರೆಯಬೇಡಿ. ನಮಗೆ ಅವು ಎಂದೂ ಬೇಕಿಲ್ಲ.",
  "start.tooShort": "ಸ್ವಲ್ಪ ಹೆಚ್ಚು ಬರೆಯಿರಿ — ಒಂದು ವಾಕ್ಯವೂ ಸರಿಯಾದ ವರ್ಗ ಆರಿಸಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ.",
  "start.error": "ಇದು ಕಳುಹಿಸಲಾಗಲಿಲ್ಲ. ನೀವು ಬರೆದದ್ದು ಸುರಕ್ಷಿತವಾಗಿದೆ. ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
  "start.saveError": "ಈ ಬ್ರೌಸರ್ ಕೇಸ್ ಫೈಲ್ ಅನ್ನು ಉಳಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. ಈ ಪುಟವನ್ನು ತೆರೆದಿಡಿ, ಕೆಲವು ಸಾಧನ ಸಂಗ್ರಹಣೆಯನ್ನು ಮುಕ್ತಗೊಳಿಸಿ ಅಥವಾ ಬ್ರೌಸರ್ ಗೌಪ್ಯತೆ ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಬದಲಾಯಿಸಿ, ನಂತರ ಮತ್ತೆ ಕೇಸ್ ರಚಿಸಲು ಪ್ರಯತ್ನಿಸಿ.",
  "start.voiceUnsupported": "ಈ ಬ್ರೌಸರ್ ರೆಕಾರ್ಡ್ ಮಾಡಲಾರದು. ದಯವಿಟ್ಟು ಬರೆದು ತಿಳಿಸಿ.",
