  "case.deleteConfirm": "ಇದು Kavach ಕೇಸ್ ದಾಖಲೆಯನ್ನು ಶಾಶ್ವತವಾಗಿ ತೆಗೆದುಹಾಕುತ್ತದೆ, ನಂತರ ಅದಕ್ಕಾಗಿ ಸಂಗ್ರಹಿಸಲಾದ ಪ್ರತಿಯೊಂದು ಸಾಕ್ಷ್ಯದ ಫೈಲ್ ಅನ್ನು ತೆಗೆದುಹಾಕುವಂತೆ ಬ್ರೌಸರನ್ನು ಕೇಳುತ್ತದೆ. Kavach ಅಳಿಸಿದ ಡೇಟಾವನ್ನು ಮರುಪಡೆಯಲು ಸಾಧ್ಯವಿಲ್ಲ; ನಿಮಗೆ ಇನ್ನೂ ಬೇಕಾದ ಯಾವುದೇ ಮೂಲಪ್ರತಿಗಳನ್ನು ಇಟ್ಟುಕೊಳ್ಳಿ. ಸ್ಥಳೀಯ ಸಾಕ್ಷ್ಯ ಶುಚಿಗೊಳಿಸುವಿಕೆ ವಿಫಲವಾದರೆ, ನಾವು ನಿಮಗೆ ತಿಳಿಸುತ್ತೇವೆ.",
  "case.deleting": "ಸ್ಥಳೀಯ ಕೇಸ್ ಅನ್ನು ಅಳಿಸಲಾಗುತ್ತಿದೆ…",
  "case.deleteError": "ಬ್ರೌಸರ್ ಕೇಸ್-ದಾಖಲೆ ಅಳಿಸುವಿಕೆಯನ್ನು ಉಳಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ, ಆದ್ದರಿಂದ ದಾಖಲೆ ಮತ್ತು ಅದರ ಸಾಕ್ಷ್ಯವನ್ನು ಇರಿಸಿಕೊಳ್ಳಲಾಗಿದೆ. ಬ್ರೌಸರ್ ಸಂಗ್ರಹಣೆಯನ್ನು ಪರಿಶೀಲಿಸಿ ಮತ್ತು ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
  "case.deleteCleanupError": "ಕೇಸ್ ದಾಖಲೆಯನ್ನು ತೆಗೆದುಹಾಕಲಾಗಿದೆ, ಆದರೆ ಬ್ರೌಸರ್ ಅದರ ಸ್ಥಳೀಯ ಸಾಕ್ಷ್ಯ ಸಂಗ್ರಹಣೆಯ ಶುಚಿಗೊಳಿಸುವಿಕೆಯನ್ನು ಪರಿಶೀಲಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. ಸಾಕ್ಷ್ಯದ ಬೈಟ್‌ಗಳು ಉಳಿದಿದ್ದರೆ, ಅನಾಥ ನಕಲುಗಳನ್ನು ತೆಗೆದುಹಾಕಲು ನಿಮ್ಮ ಬ್ರೌಸರ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ Kavach ನ ಸೈಟ್ ಡೇಟಾವನ್ನು ತೆರವುಗೊಳಿಸಿ; ಇದು ನಿಮ್ಮ ಸಾಧನದಲ್ಲಿರುವ ಇತರ ಮೂಲಪ್ರತಿಗಳನ್ನು ಅಳಿಸುವುದಿಲ್ಲ.",
  "case.deleteContinue": "ನಮ್ಮ ಕೇಸ್‌ಗಳಿಗೆ ಮುಂದುವರಿಯಿರಿ",
