  "window.title": "ವಸೂಲಾತಿ ಕಿಟಕಿ",
  "window.strong": "ಈಗಲೇ ವರದಿ ಮಾಡಿ — ಪ್ರತಿ ನಿಮಿಷವೂ ಮುಖ್ಯವಾಗಬಹುದು",
  "window.fading": "ವರದಿ ಮಾಡಲು ಕಾಯಬೇಡಿ",
  "window.late": "ಹಾಗೂ ವರದಿ ಮಾಡಿ: ವಿಳಂಬವು ಪ್ರತಿಯೊಂದು ಪರಿಹಾರವನ್ನು ಕೊನೆಗೊಳಿಸುವುದಿಲ್ಲ",
  "window.expired": "ಹಾಗೂ ವರದಿ ಮಾಡಿ ಮತ್ತು ದಾಖಲೆಯನ್ನು ಸಂರಕ್ಷಿಸಿ",
  "window.sub.strong": "1930 ಗೆ ಕರೆ ಮಾಡಿ ಮತ್ತು ತಕ್ಷಣವೇ ನಿಮ್ಮ ಬ್ಯಾಂಕ್‌ಗೆ ಸೂಚಿಸಿ. ಮುಂಚಿತವಾಗಿ ವರದಿ ಮಾಡುವುದರಿಂದ ಹಣವು ಮತ್ತೆ ಚಲಿಸುವ ಮೊದಲು ಭಾಗವಹಿಸುವ ಸಂಸ್ಥೆಗಳು ಕಾರ್ಯನಿರ್ವಹಿಸಲು ಸಹಾಯ ಮಾಡಬಹುದು, ಆದರೆ ಫಲಿತಾಂಶಗಳು ಬದಲಾಗುತ್ತವೆ.",
  "window.sub.fading": "1930 ಗೆ ಕರೆ ಮಾಡಿ, ನಿಮ್ಮ ಬ್ಯಾಂಕ್‌ಗೆ ಸೂಚಿಸಿ ಮತ್ತು ಸಾಧ್ಯವಾದಷ್ಟು ಬೇಗ ಅಧಿಕೃತ ಪೋರ್ಟಲ್‌ನಲ್ಲಿ ಫೈಲ್ ಮಾಡಿ. ಪ್ರತಿಯೊಂದು ಸ್ವೀಕೃತಿಯನ್ನು ಇಟ್ಟುಕೊಳ್ಳಿ.",
  "window.sub.late": "ವಿಳಂಬದ ನಂತರವೂ ವರದಿ ಮಾಡಿ. ಪೊಲೀಸ್, ಬ್ಯಾಂಕ್ ಮತ್ತು ಕುಂದುಕೊರತೆ ಮಾರ್ಗಗಳು ಸಂಗತಿಗಳು ಮತ್ತು ಅವುಗಳ ಸ್ವಂತ ಗಡುವುಗಳನ್ನು ಅವಲಂಬಿಸಿವೆ; ಇಲ್ಲಿ ಯಾವುದಕ್ಕೂ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಭರವಸೆ ನೀಡುವುದಿಲ್ಲ.",
  "window.elapsed": "ವಂಚನೆಯಾಗಿ ಕಳೆದದ್ದು",
  "window.chance": "ಕೇಸ್ ಮಟ್ಟದ ಚೇತರಿಕೆ ಅವಕಾಶವನ್ನು ಪ್ರಕಟಿಸಲಾಗಿಲ್ಲ",
  "window.noOdds": "ಯಾವುದೇ ಶೇಕಡಾವಾರು ತೋರಿಸಲಾಗಿಲ್ಲ: ಅಧಿಕೃತ ವ್ಯವಸ್ಥೆಗಳು ಪ್ರತ್ಯೇಕ ಕೇಸ್‌ಗೆ ಸಮರ್ಥನೀಯ ಚೇತರಿಕೆ ಸಂಭವನೀಯತೆಯನ್ನು ಪ್ರಕಟಿಸುವುದಿಲ್ಲ.",
