  "build.evidence.t": "ವಂಚಕ ಕಳುಹಿಸಿದ್ದೆಲ್ಲವನ್ನೂ ಅಂಟಿಸಿ",
  "build.evidence.b": "ಎಸ್‌ಎಂಎಸ್, ವಾಟ್ಸ್‌ಆ್ಯಪ್ ಸಂದೇಶ, ಇಮೇಲ್, ಬ್ಯಾಂಕ್ ಎಚ್ಚರಿಕೆ. ಕಚ್ಚಾ ಪಠ್ಯವನ್ನೇ ಅಂಟಿಸಿ — ಮುಖ್ಯವಾದ ಸಂಖ್ಯೆಗಳನ್ನು ನಾವು ತೆಗೆಯುತ್ತೇವೆ, ನೀವು ಟೈಪ್ ಮಾಡಬೇಕಿಲ್ಲ.",
