  "build.evidence.filesHint": "ಚಿತ್ರಗಳು ಮತ್ತು ಪಿಡಿಎಫ್. ಇವು ನಿಮ್ಮ ಸಾಧನದಲ್ಲೇ ಉಳಿಯುತ್ತವೆ — ಠಾಣೆಗೆ ಏನು ಒಯ್ಯಬೇಕೆಂದು ತಿಳಿಯಲಿ ಎಂದು ಪ್ರಕರಣ ಕಟ್ಟಿನಲ್ಲಿ ನಾವು ಅವುಗಳ ಪಟ್ಟಿ ಕೊಡುತ್ತೇವೆ.",
