  "rep.y.alsoAsks": "ಪೋರ್ಟಲ್ ಇವುಗಳನ್ನು ಸಹ ಕೇಳುತ್ತದೆ. ನಮಗೆ ಅವುಗಳ ಅವಶ್ಯಕತೆಯಿಲ್ಲ — ಅದಕ್ಕೆ ಕಾರಣ ಇಲ್ಲಿದೆ.",
  "rep.y.alsoBody": "cybercrime.gov.in ನಲ್ಲಿ ಇವುಗಳಲ್ಲಿ ಪ್ರತಿಯೊಂದೂ ಕಡ್ಡಾಯವಾಗಿದೆ: ಅವುಗಳಿಲ್ಲದೆ ನೀವು ಸಲ್ಲಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ. ವಂಚನೆಯ ತನಿಖೆಯನ್ನು ಪ್ರಾರಂಭಿಸಲು ಇವುಗಳಲ್ಲಿ ಯಾವುದೂ ಅಗತ್ಯವಿಲ್ಲ, ಮತ್ತು ಪ್ರತಿಯೊಂದೂ ಯಾರಾದರೂ ದೂರು ನೀಡುವುದನ್ನೇ ನಿಲ್ಲಿಸುವಂತೆ ಮಾಡುತ್ತದೆ. ನೀವು ಅವುಗಳನ್ನು ನೀಡಲು ಬಯಸಿದರೆ ಅವು ಇಲ್ಲಿವೆ, ಮತ್ತು ಅವಿಿಲ್ಲದೆಯೂ ದೂರು ಪೂರ್ಣಗೊಳ್ಳುತ್ತದೆ.",
