  "rep.r.sub": "ಇಲ್ಲಿಂದ ಯಾವುದನ್ನಾದರೂ ಬದಲಾಯಿಸಿ. ನೀವು ಸರಿಪಡಿಸುವ ಯಾವುದೂ ಉಳಿದಿರುವುದನ್ನು ಕಳೆದುಕೊಳ್ಳುವುದಿಲ್ಲ.",
