  "rep.r.offlineNote": "ನೀವು ಮರುಸಂಪರ್ಕಿಸಿದಾಗ ಏನನ್ನೂ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಕಳುಹಿಸಲಾಗುವುದಿಲ್ಲ.",
  "rep.r.mock": "ಇದು ಒಂದು ಪ್ರದರ್ಶನ ಮಾತ್ರ. ಯಾವುದೇ ಸರ್ಕಾರಿ ವ್ಯವಸ್ಥೆಗೆ ಏನನ್ನೂ ಕಳುಹಿಸಲಾಗುವುದಿಲ್ಲ, ಮತ್ತು ನಿಮಗೆ ಬರುವ ಸಂಖ್ಯೆಯು ಅಧಿಕೃತ ಸ್ವೀಕೃತಿಯಲ್ಲ. ನಿಜವಾದ ದೂರು cybercrime.gov.in ಗೆ ಅಥವಾ 1930 ಸಹಾಯವಾಣಿಗೆ ಹೋಗುತ್ತದೆ.",
  "rep.done.label": "ಸ್ಥಳೀಯ ಡ್ರಾಫ್ಟ್ ರಚಿಸಲಾಗಿದೆ",
  "rep.done.h": "ನಿಮ್ಮ Kavach ಪ್ರಕರಣವನ್ನು ಈ ಬ್ರೌಸರ್‌ನಲ್ಲಿ ಉಳಿಸಲಾಗಿದೆ.",
  "rep.done.body": "ಷರತ್ತುಬದ್ಧ ಸಮಯದ ಕಿಟಕಿಗಳನ್ನು ವೀಕ್ಷಿಸಲು, ದಾಖಲೆಗಳನ್ನು ಸಿದ್ಧಪಡಿಸಲು ಮತ್ತು ನಿಮಗೆ ನಿಜವಾಗಿ ಸ್ವೀಕರಿಸುವ ಅಧಿಕೃತ ಸ್ವೀಕೃತಿಗಳು ಅಥವಾ ಪ್ರತಿಕ್ರಿಯೆಗಳನ್ನು ಮಾತ್ರ ದಾಖಲಿಸಲು ಪ್ರಕರಣದ ಯೋಜನೆಯನ್ನು ತೆರೆಯಿರಿ.",
  "rep.done.queuedLabel": "ಸಿಗ್ನಲ್‌ಗಾಗಿ ಕಾಯಲಾಗುತ್ತಿದೆ",
  "rep.done.queuedH": "ಈ ಸಾಧನದಲ್ಲಿ ಉಳಿಸಲಾಗಿದೆ-ಕಳುಹಿಸಲು ಸರತಿಯಲ್ಲಿಲ್ಲ.",
  "rep.done.queuedBody": "ನೀವು ಆಫ್‌ಲೈನ್‌ನಲ್ಲಿದ್ದೀರಿ. ನಿಮ್ಮ ಡ್ರಾಫ್ಟ್ ಈ ಸಾಧನದಲ್ಲೇ ಉಳಿಯುತ್ತದೆ. ನಂತರ Kavach ಪ್ರಕರಣವನ್ನು ರಚಿಸಿದರೂ ಸಹ ಅದನ್ನು NCRP, ಪೊಲೀಸ್ ಅಥವಾ ನಿಮ್ಮ ಬ್ಯಾಂಕ್‌ಗೆ ಸಲ್ಲಿಸಲಾಗುವುದಿಲ್ಲ.",
  "rep.done.notFir": "Kavach ಡ್ರಾಫ್ಟ್, NCRP ಸ್ವೀಕೃತಿ ಮತ್ತು FIR ಎಂಬುದು ವಿಭಿನ್ನ ದಾಖಲೆಗಳಾಗಿವೆ. ಬಹಿರಂಗಪಡಿಸಿದ ಸಂಗತಿಗಳು ಸಂಜ್ಞೆಯ ಅಪರಾಧಕ್ಕೆ ಸಂಬಂಧಿಸಿದ್ದರೆ, BNSS ಸೆಕ್ಷನ್ 173 ಪೊಲೀಸ್-ವರದಿ ಮಾಡುವ ಮತ್ತು ಮೇಲ್ಮನವಿ ಮಾರ್ಗವನ್ನು ಒದಗಿಸುತ್ತದೆ; ಪೊಲೀಸ್ ಮಾತ್ರ ಅಧಿಕೃತ FIR ವಿವರಗಳನ್ನು ನೀಡಬಹುದು.",
  "f.category": "ವರ್ಗ",
  "f.category.why": "ದೂರನ್ನು ವಿವರಿಸಲು ಮತ್ತು ಮಾರ್ಗನಿರ್ದೇಶನ ಮಾಡಲು ಈ ವರ್ಗವು ಸಹಾಯ ಮಾಡುತ್ತದೆ. ಅಧಿಕೃತ ಪೋರ್ಟಲ್ ಅಥವಾ ಸ್ವೀಕರಿಸುವ ಏಜೆನ್ಸಿಯು ಸಂಗತಿಗಳನ್ನು ವಿಭಿನ್ನವಾಗಿ ವರ್ಗೀಕರಿಸಬಹುದುವಾದ್ದರಿಂದ ಸೂಚನೆಯನ್ನು ಪರಿಶೀಲಿಸಿ.",
  "f.category.was": "ಪೋರ್ಟಲ್ ಇದರೊಂದಿಗೆ ತೆರೆಯುತ್ತದೆ: ಏಳು ವರ್ಗಗಳ ಡ್ರಾಪ್‌ಡೌನ್, ಏನೆಂಬುದರ ಬಗ್ಗೆ ನೀವು ಏನನ್ನೂ ಹೇಳುವ ಮೊದಲು.",
