  "esc.source": "ದೂರುದಾರರಿಗಾಗಿ ಪ್ರಕಟಿಸಿದಂತೆ ಅಧಿಕಾರಿಯ ವಿವರಗಳು ಇಲ್ಲಿ ಲಭ್ಯವಿವೆ",
  "esc.fileFirst": "ನೀವು NCRP ನಲ್ಲಿ ದೂರು ದಾಖಲಿಸಿದ್ದರೆ, ಟ್ರ್ಯಾಕಿಂಗ್ ಮಾಡಲು ಸ್ವೀಕೃತಿ ಸಂಖ್ಯೆಯನ್ನು ಇಟ್ಟುಕೊಳ್ಳಿ. ಇತರ ಪೊಲೀಸ್, ಬ್ಯಾಂಕ್ ಮತ್ತು ನಿಯಂತ್ರಕರ ಮಾರ್ಗಗಳು ತಮ್ಮದೇ ಆದ ಮುಂಗಡ ಅವಶ್ಯಕತೆಗಳನ್ನು ಹೊಂದಿರಬಹುದು.",
