  "doc.inEnglish": "ಇಂಗ್ಲಿಷಿನಲ್ಲಿ ಕಳುಹಿಸಲಾಗುತ್ತದೆ",
  "doc.inYourLang": "ನಿಮ್ಮ ಭಾಷೆಯಲ್ಲಿ ಓದಿ",
  "doc.whyEnglish": "ಠಾಣೆಗಳು ಮತ್ತು ಬ್ಯಾಂಕುಗಳು ಇಂಗ್ಲಿಷಿನಲ್ಲಿ ಕೆಲಸ ಮಾಡುತ್ತವೆ. ಆದರೂ ನೀವು ಸಹಿ ಹಾಕುತ್ತಿರುವುದನ್ನು ಓದಲು ಸಾಧ್ಯವಾಗಬೇಕು, ಹಾಗಾಗಿ ನಾವು ಎರಡನ್ನೂ ತೋರಿಸುತ್ತೇವೆ.",
  "doc.readyLabel": "ಸಿದ್ಧ",
  "doc.needsLabel": "ಇನ್ನಷ್ಟು ಮಾಹಿತಿ ಬೇಕು",
  "doc.needs": "ಮೊದಲು ಇದನ್ನು ಸೇರಿಸಿ",
  "doc.ncrp.t": "ಎನ್‌ಸಿಆರ್‌ಪಿ ದೂರಿನ ವಿವರಣೆ",
  "doc.ncrp.b": "ಇದನ್ನು ನೇರವಾಗಿ cybercrime.gov.in ನ ವಿವರಣೆ ಪೆಟ್ಟಿಗೆಯಲ್ಲಿ ಅಂಟಿಸಿ. ಇದು 200 ಅಕ್ಷರಗಳ ಕನಿಷ್ಠ ಮಿತಿಗಿಂತ ಹೆಚ್ಚಿದೆ ಮತ್ತು ಪೋರ್ಟಲ್ ತಿರಸ್ಕರಿಸುವ ಚಿಹ್ನೆಗಳು ಇದರಲ್ಲಿ ಇಲ್ಲ.",
  "doc.script.t": "ನಿಮ್ಮ 1930 ಕರೆಯ ಸ್ಕ್ರಿಪ್ಟ್",
  "doc.script.b": "ಇದನ್ನು ಓದಿ ಹೇಳಿ. ಆಪರೇಟರ್‌ಗೆ ಈ ಸಂಗತಿಗಳು ಇದೇ ಕ್ರಮದಲ್ಲಿ ಬೇಕು, ಮತ್ತು ಸಿದ್ಧವಾಗಿದ್ದರೆ ಕರೆ ಬೇಗ ಮುಗಿಯುತ್ತದೆ.",
  "doc.bank.t": "ನಿಮ್ಮ ಬ್ಯಾಂಕಿಗೆ ಪತ್ರ",
  "doc.bank.b": "ದಿನಾಂಕದೊಂದಿಗೆ ಸ್ವೀಕೃತಿಯನ್ನು ನೀಡುವ ಚಾನೆಲ್ ಮೂಲಕ ಕಳುಹಿಸಿ. ಬ್ಯಾಂಕ್ ಅನ್ವಯವಾಗುವ RBI ನಿಯಮಗಳ ಅಡಿಯಲ್ಲಿ ವಹಿವಾಟನ್ನು ಮೌಲ್ಯಮಾಪನ ಮಾಡಬೇಕು; ಈ ಪತ್ರವು ಸ್ವತಃ ಶೂನ್ಯ ಹೊಣೆಗಾರಿಕೆಯನ್ನು ಸೃಷ್ಟಿಸುವುದಿಲ್ಲ.",
  "doc.fir.t": "ಎಫ್‌ಐಆರ್ ಅರ್ಜಿ",
  "doc.fir.b": "ಎರಡು ಪ್ರತಿ ಮುದ್ರಿಸಿ, ಎರಡರಲ್ಲೂ ಸಹಿ ಮಾಡಿ, ಠಾಣೆಗೆ ಒಯ್ಯಿರಿ. ಒಂದರ ಮೇಲೆ ಮುದ್ರೆ ಒತ್ತಿಸಿ ವಾಪಸು ಪಡೆಯಿರಿ.",
  "doc.chakshu.t": "ಚಕ್ಷು ವರದಿ",
  "doc.chakshu.b": "ಸಂಚಾರ್ ಸಾಥಿಯಲ್ಲಿ ವಂಚಕನ ಸಂಖ್ಯೆಯನ್ನು ವರದಿ ಮಾಡುವಾಗ ತುಂಬಬೇಕಾದ ವಿವರಗಳು.",
  "doc.mrm.t": "ಹಣ ಮರುಸ್ಥಾಪನೆ ವಿನಂತಿ",
  "doc.mrm.b": "mrm-ncrp.mha.gov.in ನಲ್ಲಿ ನಮೂದಿಸಬೇಕಾದ ಪ್ರತಿಯೊಂದು ಮೌಲ್ಯ, ಪೋರ್ಟಲ್ ಕೇಳುವ ಕ್ರಮದಲ್ಲಿ, ಜೊತೆಗೆ ಬಿಡುಗಡೆ ಆದೇಶವನ್ನು ಕೇಳಲು ನಿಮ್ಮ ತನಿಖಾ ಅಧಿಕಾರಿಗೆ ನೀಡಬೇಕಾದ ಟಿಪ್ಪಣಿ.",
  "doc.ombudsman.t": "ಒಂಬುಡ್ಸ್‌ಮನ್ ದೂರು",
  "doc.ombudsman.b": "ನಿಯಂತ್ರಿತ ಸಂಸ್ಥೆಗೆ ಮೊದಲು ದೂರು ನೀಡಿ ತೃಪ್ತಿಕರವಲ್ಲದ ಉತ್ತರವನ್ನು ಪಡೆದ ನಂತರ ಅಥವಾ ಅನ್ವಯವಾಗುವ 30 ದಿನಗಳ ಅಥವಾ ಅದಕ್ಕಿಂತ ಹೆಚ್ಚಿನ ಪ್ರತಿಕ್ರಿಯೆ ಅವಧಿಯ ನಂತರ ಮಾತ್ರ ಇದನ್ನು ಬಳಸಿ. ಪ್ರತ್ಯೇಕ 90 ದಿನಗಳ ದೂರು ದಾಖಲೆ ಮಿತಿ ಮತ್ತು ಪ್ರತಿಯೊಂದು ಸ್ವೀಕೃತಿ ದಿನಾಂಕವನ್ನು ಪರಿಶೀಲಿಸಿ.",
  "ask.t": "ನಿಮ್ಮ ಪ್ರಕರಣದ ಬಗ್ಗೆ ಕೇಳಿ",
  "ask.b": "ಉತ್ತರಗಳು ನಿಮ್ಮ ಪ್ರಕರಣ ಕಡತವನ್ನು ಆಧರಿಸಿವೆ. ಇದು ಕಾನೂನು ಸಲಹೆಯಲ್ಲ.",
  "ask.ph": "ಏನು ಬೇಕಾದರೂ ಕೇಳಿ — ಉದಾ., ಪೊಲೀಸರು ಎಫ್‌ಐಆರ್ ತೆಗೆದುಕೊಳ್ಳಲು ನಿರಾಕರಿಸಿದರೆ?",
  "ask.send": "ಕೇಳಿ",
  "ask.thinking": "ಯೋಚಿಸುತ್ತಿದ್ದೇವೆ",
  "ask.s1": "ಪೊಲೀಸರು ನನ್ನ ಎಫ್‌ಐಆರ್ ತೆಗೆದುಕೊಳ್ಳಲು ನಿರಾಕರಿಸಿದರೆ ಏನು ಮಾಡಲಿ?",
  "ask.s2": "ಬ್ಯಾಂಕ್ ತಪ್ಪು ನನ್ನದೇ ಎನ್ನುತ್ತದೆ. ಈಗ ಏನು?",
  "ask.s3": "ಪೋರ್ಟಲ್‌ನಲ್ಲಿ ವಿಲೇವಾರಿಯಾಗಿದೆ ಎಂದಿದೆ. ಎಲ್ಲ ಮುಗಿಯಿತೇ?",
  "ask.s4": "ಒಂದು ತಿಂಗಳ ನಂತರವೂ ಹಣ ವಾಪಸು ಸಿಗಬಹುದೇ?",
  "g.loading": "ಲೋಡ್ ಆಗುತ್ತಿದೆ",
  "g.retry": "ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ",
  "g.close": "ಮುಚ್ಚಿ",
  "g.cancel": "ಬೇಡ",
  "g.confirm": "ಖಚಿತ",
  "g.back": "ಹಿಂದೆ",
  "g.yes": "ಹೌದು",
  "g.no": "ಇಲ್ಲ",
  "g.notSet": "ಕೊಟ್ಟಿಲ್ಲ",
  "g.today": "ಇಂದು",
  "g.tomorrow": "ನಾಳೆ",
  "g.days": "ದಿನ",
  "g.hours": "ಗಂಟೆ",
