  "g.aiNote": "ನೀವು ಹೇಳಿದ್ದರಿಂದ ಎಐ ಬರೆದಿದೆ. ಕಳುಹಿಸುವ ಮೊದಲು ಓದಿ.",
  "g.offline": "ನೀವು ಆಫ್‌ಲೈನ್‌ನಲ್ಲಿದ್ದೀರಿ. ನೀವು ತುಂಬಿದ ಎಲ್ಲವೂ ಉಳಿದಿದೆ.",
  "doc.share": "ಹಂಚಿಕೊಳ್ಳಿ",
  "demo.label": "ಕೆಲಸ ಮಾಡುವುದನ್ನು ನೋಡಿ",
  "demo.h1": "ಎರಡು ನಿಮಿಷ,",
  "demo.h2": "ಆರಂಭದಿಂದ ಕೊನೆಯವರೆಗೆ.",
  "demo.sub": "ಒಂದು ಪ್ರೊಟೊಟೈಪ್ ರನ್: ನಾಗರಿಕರೊಬ್ಬರು ವಂಚನೆಯನ್ನು ವಿವರಿಸುತ್ತಾರೆ, ಹೊರತೆಗೆಯப்பட்ட ಸತ್ಯಗಳನ್ನು ಪರಿಶೀಲಿಸುತ್ತಾರೆ ಮತ್ತು ದಾಖಲಾಗದ ಕೇಸ್ ಪ್ಲಾನ್ ಹಾಗೂ ಸ್ಪಷ್ಟವಾಗಿ ಲೇಬಲ್ ಮಾಡಿದ ಡ್ರಾಫ್ಟ್‌ಗಳೊಂದಿಗೆ ಹೊರಡುತ್ತಾರೆ.",
