  "demo.volume": "ಶಬ್ದ",
  "demo.unsupported": "ಈ ಬ್ರೌಸರ್ ವೀಡಿಯೊವನ್ನು ಇಲ್ಲಿಯೇ ಚಲಾಯಿಸಲಾಗದು.",
  "g.demoMode": "ಡೆಮೊ ಮೋಡ್ — ಎಐ ಕೀ ಇಲ್ಲ, ಹಾಗಾಗಿ ಉತ್ತರಗಳು ಅಂತರ್ನಿರ್ಮಿತ ನಿಯಮ ಎಂಜಿನ್‌ನಿಂದ ಬರುತ್ತಿವೆ.",
  "nav.demo": "ಡೆಮೊ ನೋಡಿ",
  "start.voiceNothing": "ನಮಗೆ ಏನೂ ಕೇಳಿಸಲಿಲ್ಲ. ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ, ಅಥವಾ ಕೆಳಗೆ ಬರೆಯಿರಿ.",
  "intake.title": "ಒಮ್ಮೆ ಹೇಳಿ. ನಾವು ನಿಮ್ಮೊಂದಿಗೆ ಪ್ರಕರಣವನ್ನು ಸಿದ್ಧಪಡಿಸುತ್ತೇವೆ.",
  "intake.sub": "ಶಾಂತಿಯುತವಾದ, ಪ್ರಶ್ನೆ-ಪ್ರಶ್ನೆಯ ಸಂದರ್ಶನ. ಮತ್ತೆ ಪ್ರಾರಂಭಿಸದೆ ಚಾಟ್, WhatsApp ಪೂರ್ವವೀಕ್ಷಣೆ ಮತ್ತು Vaani ಕರೆಯ ನಡುವೆ ಬದಲಿಸಿ.",
  "intake.progress": "ಪ್ರಕರಣದ ತಿಳುವಳಿಕೆ",
  "intake.saved": "ಈ ಸಾಧನದಲ್ಲಿ ಉಳಿಸಲಾಗಿದೆ",
  "intake.switch": "ನಾವು ಹೇಗೆ ಮಾತನಾಡುತ್ತೇವೆ",
  "intake.channel.voice": "Vaani ಕರೆ",
  "intake.channel.voiceNote": "Vaani-ಸಿದ್ಧ ಧ್ವನಿ ಸಂದರ್ಶನ",
  "intake.agentName": "Kavach Saathi",
  "intake.agentRole": "ಪ್ರಕರಣ ಮಾರ್ಗದರ್ಶಿ",
  "begin.h1": "ನಿಮಗೆ ಸಹಾಯ ಪಡೆಯೋಣ.",
  "begin.step": "ಪ್ರಶ್ನೆ",
  "begin.of": "ರಲ್ಲಿ",
  "begin.chooseH": "ಏನಾಯಿತು ಎಂದು ನೀವು ನಮಗೆ ಹೇಗೆ ತಿಳಿಸಲು ಬಯಸುತ್ತೀರಿ?",
  "begin.chooseSub": "ಯಾವ ರೀತಿಯಲ್ಲಿಯೂ, ಅದೇ ಪ್ರಕರಣ ನಿರ್ಮಾಣವಾಗುತ್ತದೆ. ನೀವು ನಂತರ ಬದಲಾಯಿಸಬಹುದು.",
  "begin.voiceH": "Kavach Saathi ಜತೆಗೆ ಮಾತನಾಡA",
  "begin.voiceNote": "ನಿಮ್ಮ ಸ್ವಂತ ಭಾಷೆಯಲ್ಲಿ ಮಾತನಾಡಿ. ಯಾವುದೇ ಫೋನ್ ಸಂಖ್ಯೆ ಅಗತ್ಯವಿಲ್ಲ — ಇದು ಈ ಟ್ಯಾಬ್‌ನಲ್ಲಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ.",
  "begin.formLink": "ಫಾರ್ಮ್ ಬಯಸುತ್ತೀರಾ? ಐದು ಹಂತಗಳ ಆವೃತ್ತಿಯನ್ನು ಬಳಸಿ",
  "begin.back": "ಹಿಂದಕ್ಕೆ",
  "begin.boundaryNote": "ನಿಮ್ಮ ಪ್ರಕರಣಕ್ಕೆ ಸಹಾಯ ಮಾಡುವುದನ್ನು ಮಾತ್ರ ನಾವು ಕೇಳುತ್ತೇವೆ. OTP, PIN, ಪಾಸ್‌ವರ್ಡ್, CVV, ಪೂರ್ಣ ಕಾರ್ಡ್ ಸಂಖ್ಯೆ ಅಥವಾ Aadhaar ಸಂಖ್ಯೆಯನ್ನು ಎಂದಿಗೂ ಹಂಚಿಕೊಳ್ಳಬೇಡಿ. Kavach ಸ್ವತಂತ್ರವಾಗಿದೆ — ಪೊಲೀಸ್ ಅಲ್ಲ, ಸರ್ಕಾರವಲ್ಲ.",
  "intake.boundaryQ": "ನಾವು ಪ್ರಾರಂಭಿಸುವ ಮೊದಲು, ಒಂದು ಪ್ರಮುಖ ಭರವಸೆ.",
  "intake.boundaryBody": "ನಿಮ್ಮ ಪ್ರಕರಣಕ್ಕೆ ಸಹಾಯ ಮಾಡುವ ಅಂಶಗಳನ್ನು ಮಾತ್ರ ನಾನು ಕೇಳುತ್ತೇನೆ. ಇಲ್ಲಿ ಎಂದಿಗೂ OTP, ಪಿನ್, ಪಾಸ್‌ವರ್ಡ್, CVV, ಪೂರ್ಣ ಕಾರ್ಡ್ ಸಂಖ್ಯೆ ಅಥವಾ Aadhaar ಸಂಖ್ಯೆಯನ್ನು ಹಂಚಿಕೊಳ್ಳಬೇಡಿ. Kavach ಸ್ವತಂತ್ರವಾಗಿದೆ, ಇದು ಪೊಲೀಸ್ ಅಥವಾ ಸರ್ಕಾರಿ ಸೇವೆಯಲ್ಲ.",
  "intake.boundaryDetails": "ಈ ಪ್ರೊಟೊಟೈಪ್‌ನಲ್ಲಿ, ನಿಮ್ಮ ಪ್ರಕರಣವನ್ನು ಈ ಬ್ರೌಸರ್‌ನಲ್ಲಿ ಉಳಿಸಲಾಗಿದೆ. ವಿಶ್ಲೇಷಿಸಲು ನೀವು AI ಅನ್ನು ಕೇಳುವ ಪಠ್ಯವನ್ನು ಕಾನ್ಫಿಗರ್ ಮಾಡಿದ ಮಾದರಿ ಒದಗಿಸುವವರಿಗೆ ಕಳುಹಿಸಲಾಗುತ್ತದೆ. WhatsApp-ಶೈಲಿಯ ಪೂರ್ವವೀಕ್ಷಣೆ ಈ ಬ್ರೌಸರ್‌ನಲ್ಲೇ ಇರುತ್ತದೆ. ಲೈವ್ Vaani ಪರೀಕ್ಷಾ ಕಾಲ್‌ಬ್ಯಾಕ್‌ಗೆ ಪ್ರತ್ಯೇಕ ಒಪ್ಪಿಗೆ ಮತ್ತು ಅನುಮತಿ ಪಟ್ಟಿಯಲ್ಲಿರುವ ಸಂಖ್ಯೆಯ ಅಗತ್ಯವಿದೆ.",
  "intake.boundaryCta": "ನನಗೆ ಅರ್ಥವಾಗಿದೆ — ಪ್ರಾರಂಭಿಸಿ",
  "intake.safetyQ": "ನೀವು ಅಥವಾ ಬೇರೆ ಯಾರಾದರೂ ಈ ಕ್ಷಣದಲ್ಲಿ ತಕ್ಷಣದ ದೈಹಿಕ ಅಪಾಯದಲ್ಲಿದ್ದೀರಾ?",
  "intake.safetySafe": "ಇಲ್ಲ, ನಾನು ಈಗ ಸುರಕ್ಷಿತವಾಗಿದ್ದೇನೆ",
  "intake.safetyDanger": "ಹೌದು, ಯಾರಾದರೂ ಅಪಾಯದಲ್ಲಿರಬಹುದು",
  "intake.preferNot": "ಹೇಳದಿರಲು ಬಯಸುತ್ತೇನೆ",
