  "intake.emergencyBody": "112 ಗೆ ಕರೆ ಮಾಡಿ ಅಥವಾ ಸುರಕ್ಷಿತ ಸ್ಥಳಕ್ಕೆ ತೆರಳಿ ಮತ್ತು ಸಹಾಯಕ್ಕಾಗಿ ನೀವು ನಂಬುವ ಯಾರನ್ನಾದರೂ ಕೇಳಿ. ಈ ಸಂದರ್ಶನವು ತುರ್ತು ಸೇವೆಗಳನ್ನು ಕಳುಹಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ.",
  "intake.emergencyCall": "ಈಗಲೇ 112 ಗೆ ಕರೆ ಮಾಡಿ",
  "intake.emergencyContinue": "ನನಗೆ ಸಹಾಯ ಸಿಕ್ಕಿದೆ — ಮುಂದುವರಿಸಿ",
  "intake.ageQ": "ಇದು 18 ವರ್ಷಕ್ಕಿಂತ ಕಡಿಮೆ ವಯಸ್ಸಿನವರ ಕುರಿತೇ? ಮಕ್ಕಳ ಸುರಕ್ಷತೆ ಮತ್ತು ವರದಿ ಮಾಡುವ ನಿಯಮಗಳು ಭಿನ್ನವಾಗಿರುವುದರಿಂದ ನಾನು ಕೇಳುತ್ತಿದ್ದೇನೆ.",
