  "intake.ageChildOther": "ಇದು ಇನ್ನೊಬ್ಬ ಮಗುವಿನ ಕುರಿತಾಗಿದೆ",
  "intake.childH": "ಮಗುವನ್ನು ರಕ್ಷಿಸಿ ಮತ್ತು ಲೈಂಗಿಕ ವಸ್ತುಗಳನ್ನುForward ಮಾಡಬೇಡಿ.",
  "intake.childBody": "ಮಗುವಿಗೆ ಅಪಾಯವಿದ್ದರೆ, 112 ಕರೆ ಮಾಡಿ. ಮಕ್ಕಳ ಸಹಾಯಕ್ಕಾಗಿ, 1098 ಕರೆ ಮಾಡಿ. ಲೈಂಗಿಕ ಚಿತ್ರಗಳು ಅಥವಾ ವೀಡಿಯೊಗಳನ್ನು ಇಲ್ಲಿ ಅಪ್‌ಲೋಡ್ ಮಾಡಬೇಡಿ, ಹೊಸ ಪ್ರತಿಗಳನ್ನು ಉಳಿಸಬೇಡಿ ಅಥವಾ ಫಾರ್ವರ್ಡ್ ಮಾಡಬೇಡಿ. ಈ ಪ್ರೊಟೊಟೈಪ್‌ನಲ್ಲಿ ಯಾವುದೇ ಸಿಬ್ಬಂದಿ ಕಡ್ಡಾಯ-ವರದಿ ಮಾಡುವ ತಂಡವಿಲ್ಲ; ವಿಶ್ವಾಸಾರ್ಹ ವಯಸ್ಕರು ಅಥವಾ ತರಬೇತಿ ಪಡೆದ ವ್ಯಕ್ತಿಯು ಇದನ್ನು ವಹಿಸಿಕೊಳ್ಳಬೇಕು.",
