  "intake.childContinue": "ಹಾನಿಕಾರಕ ಮಾಧ್ಯಮವಿಲ್ಲದೆ ಮುಂದುವರಿಸಿ",
  "intake.moneyQ": "ನಿಮ್ಮ ಬ್ಯಾಂಕ್ ಖಾತೆ, ಕಾರ್ಡ್, UPI ಅಪ್ಲಿಕೇಶನ್ ಅಥವಾ ವಾಲೆಟ್‌ನಿಂದ ಹಣ ಹೊರಹೋದೆಯೇ?",
  "intake.moneyYes": "ಹೌದು, ಹಣ ಹೊರಹೋಗಿದೆ",
