  "intake.urgentH": "ಇಲ್ಲಿ ನಿಲ್ಲಿಸಿ ಮತ್ತು ಈಗಲೇ ಹಣಕಾಸಿನ ವಂಚನೆಯನ್ನು ವರದಿ ಮಾಡಿ.",
  "intake.urgentBody": "ಸಾಧ್ಯವಾದಷ್ಟು ಬೇಗ 1930 ಕರೆ ಮಾಡಿ. ಸಹಾಯವಾಣಿಯು ವಂಚನೆಯನ್ನು ದಾಖಲಿಸಬಹುದು ಮತ್ತು ಭಾಗವಹಿಸುವ ಹಣಕಾಸು ಸಂಸ್ಥೆಗಳನ್ನು ಎಚ್ಚರಿಸಬಹುದು; ಇದು ಸ್ಥಬಂಧ (freeze) ಅಥವಾ ಮರುಪಾವತಿಯನ್ನು ಖಾತರಿಪಡಿಸುವುದಿಲ್ಲ. ಈ ಟ್ಯಾಬ್ ಅನ್ನು ಬಿಡುವ ಮೊದಲು ಸೇವ್ ಸೂಚಕವನ್ನು ಪರಿಶೀಲಿಸಿ.",
  "intake.thankYou": "ಧನ್ಯವಾದಗಳು",
  "intake.storyQ": "ಈಗ ಮೊದಲ ಕರೆ ಅಥವಾ ಸಂದೇಶದಿಂದ ಮುಂದೇನು ಆಯಿತು ಎಂಬುದರವರೆಗೆ ಏನಾಯಿತು ಎಂದು ನನಗೆ ತಿಳಿಸಿ.",
  "intake.storyHint": "ನಿಮ್ಮ ಸ್ವಂತ ಭಾಷೆ ಮತ್ತು ಸಾಮಾನ್ಯ ಪದಗಳನ್ನು ಬಳಸಿ. ಹೆಸರುಗಳು, ಫೋನ್ ಸಂಖ್ಯೆಗಳು, UPI ID ಗಳು, ದಿನಾಂಕಗಳು ಮತ್ತು ವಹಿವಾಟು ಉಲ್ಲೇಖಗಳು ಸಹಾಯ ಮಾಡುತ್ತವೆ. ರಹಸ್ಯಗಳು ಮತ್ತು ಗುರುತಿನ ಸಂಖ್ಯೆಗಳನ್ನು ಬಿಟ್ಟುಬಿಡಿ.",
  "intake.storyCta": "ನನ್ನ ಪ್ರಕರಣವನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಿ",
  "intake.storyShort": "ಏನಾಯಿತು ಎಂದು ನಾನು ಊಹಿಸದಂತೆ ದಯವಿಟ್ಟು ಒಂದೆರಡು ವಿವರಗಳನ್ನು ಸೇರಿಸಿ.",
  "intake.analysing": "ಸಮಯರೇಖೆ, ಗುರುತಿನ ಚೀಟಿಗಳು ಮತ್ತು ಕಾಣೆಯಾದ ಸಂಗತಿಗಳಿಗಾಗಿ ಆಲಿಸಲಾಗುತ್ತಿದೆ",
  "intake.verifyQ": "ನಾನು ಅರ್ಥಮಾಡಿಕೊಂಡದ್ದು ಇಲ್ಲಿದೆ. ನಿಮ್ಮ ಕೇಸ್ ಫೈಲ್ ಪ್ರವೇಶಿಸುವ ಮೊದಲು ದಯವಿಟ್ಟು ಇದನ್ನು ಸರಿಪಡಿಸಿ.",
  "intake.verifySub": "ನೀವು ಅದನ್ನು ಖಚಿತಪಡಿಸುವವರೆಗೆ ಸಲಜೆಯು ಸತ್ಯವಲ್ಲ.",
  "intake.reviewH": "ನನಗೆ ಅರ್ಥವಾದದ್ದು",
  "intake.verifyWhere": "ಇದೆಲ್ಲವೂ ಈ ಚಾಟ್‌ನ ಪಕ್ಕದಲ್ಲಿರುವ ಪ್ಯಾನೆಲ್‌ನಲ್ಲಿದೆ ಮತ್ತು ಅಲ್ಲೇ ಇರುತ್ತದೆ. ತಪ್ಪಿರುವುದನ್ನು ಸರಿಪಡಿಸಿ — ನೀವು ಟೈಪ್ ಮಾಡಿದಂತೆ ಅದು ಅಪ್‌ಡೇಟ್ ಆಗುತ್ತದೆ.",
