  "intake.verifyBankAlertHint": "ಇದು—ಅಂದಾಜು ಘಟನೆಯ ಸಮಯವಲ್ಲ—RBI ಮೂರು-ಕೆಲಸದ ದಿನಗಳ ಲೆಕ್ಕಾಚಾರದ ಪ್ರಚೋದಕವಾಗಿದೆ. ಗೊತ್ತಿಲ್ಲದಿದ್ದರೆ ಅದನ್ನು ಖಾಲಿಯಾಗಿ ಬಿಡಿ.",
