  "intake.rbiInitiationQ": "ವಿವಾದಿತ ಪಾವತಿಗಾಗಿ, ಯಾರಾದರೂ ನಿಮಗೆ ಮೋಸ ಮಾಡಿದ್ದರೆ ಅಥವಾ ಒತ್ತಡ ಹೇರಿದ್ದರೂ ಸಹ ನೀವೇ ಅದನ್ನು ಮಾಡಿದ್ದೀರಾ ಅಥವಾ ಅನುಮೋದಿಸಿದ್ದೀರಾ?",
