  "intake.rbiInitiatedNotMe": "ನಾನು ಮಾಡಿಲ್ಲ ಅಥವಾ ಅನುಮೋದಿಸಿಲ್ಲ",
  "intake.rbiCredentialQ": "OTP, PIN, ಪಾಸ್‌ವರ್ಡ್ ಅಥವಾ ಇತರ ಪಾವತಿ ಪ್ರಮಾಣಪತ್ರವನ್ನು ಹಂಚಿಕೊಳ್ಳುವುದು ಈ ವಿವಾದಿತ ವಹಿವಾಟಿಗೆ ಕಾರಣವಾಯಿತು ಅಥವಾ ಅನುವು ಮಾಡಿಕೊಟ್ಟಿತು ಎಂದು ತೋರುತ್ತದೆಯೇ? ಏನೋ ಹಂಚಿಕೊಳ್ಳಲಾಗಿದೆ ಎಂದು ಮಾತ್ರ ನಿಮಗೆ ತಿಳಿದಿದ್ದರೆ ‘ಖಚಿತವಿಲ್ಲ’ ಆಯ್ಕೆಮಾಡಿ. ಇದು ದೋಷಾರೋಪಣೆ ಪ್ರಶ್ನೆಯಲ್ಲ.",
