  "intake.rbiCredentialNo": "ಇಲ್ಲ—ಯಾವುದನ್ನೂ ಹಂಚಿಕೊಳ್ಳಲಾಗಿಲ್ಲ, ಅಥವಾ ಇದು ಸಕ್ರಿಯಗೊಳಿಸಿಲ್ಲ",
  "intake.rbiBankFaultQ": "ಬ್ಯಾಂಕ್ ಕಡೆಯ ಸುರಕ್ಷತಾ ವೈಫಲ್ಯ, ವಂಚನೆ, ನಿರ್ಲಕ್ಷ್ಯ ಅಥವಾ ಸೇವಾ ದೋಷವನ್ನು ಶಂಕಿಸಲು ನಿಮ್ಮ ಬಳಿ ನಿರ್ದಿಷ್ಟ ಕಾರಣವಿದೆಯೇ?",
  "intake.rbiBankFaultYes": "ಹೌದು, ನಾನು ಬ್ಯಾಂಕ್ ಕಡೆಯ ವೈಫಲ್ಯವನ್ನು ಶಂಕಿಸುತ್ತೇನೆ",
