  "intake.rbiReportAfter": "7 working days ನಂತರ",
  "intake.rbiReportNo": "ನಾನು ಬ್ಯಾಂಕ್‌ಗೆ ತಿಳಿಸಿಲ್ಲ",
  "intake.rbiReviewQ": "ಈ ಉತ್ತರಗಳು ಯಾವ RBI ರಕ್ಷಣಾ ಮಾರ್ಗ ಅನ್ವಯಿಸಬಹುದು ಎಂಬುದನ್ನು ಬದಲಾಯಿಸುತ್ತವೆ. ಇದು ಮರುಪಾವತಿಯ ಭರವಸೆಯಲ್ಲ, ಎಚ್ಚರಿಕೆಯ ಮೂಲ-ಸಂಯೋಜಿತ ಸ್ಕ್ರೀನಿಂಗ್ ಆಗಿದೆ.",
  "intake.rbiCardEyebrow": "RBI ರಕ್ಷಣಾ ಪರದೆ",
