  "intake.rbiDisclaimer": "ಈ ಪರದೆಯು ಅನಧಿಕೃತ ಎಲೆಕ್ಟ್ರಾನಿಕ್ ಬ್ಯಾಂಕಿಂಗ್ ವಹಿವಾಟುಗಳಿಗೆ ಮಾತ್ರ RBI/2017-18/15 ಅನ್ನು ಅನ್ವಯಿಸುತ್ತದೆ. ಬ್ಯಾಂಕ್ ಸಂಗತಿಗಳನ್ನು ನಿರ್ಧರಿಸಬೇಕು; ಇತರ ಪರಿಹಾರಗಳು ಇನ್ನೂ ಅಸ್ತಿತ್ವದಲ್ಲಿರಬಹುದು.",
  "intake.rbiSource": "ಅಧಿಕೃತ RBI ಸುತ್ತೋಲೆಯನ್ನು ಓದಿ",
  "intake.rbiContinue": "ನಾನು ಇದನ್ನು ಓದಿದ್ದೇನೆ — ಮುಂದುವರಿಸಿ",
  "intake.rbiProtectionZero": "ಉತ್ತರಗಳು ಷರತ್ತುಬದ್ಧ ಶೂನ್ಯ-ಹೊಣೆಗಾರಿಕೆ ಮಾರ್ಗಕ್ಕೆ ಹೊಂದಿಕೊಳ್ಳುತ್ತವೆ",
