  "intake.rbiProtectionPolicy": "ಬ್ಯಾಂಕ್‌ನ ಪ್ರಕಟಿತ ನೀತಿಯು ನಿಯಂತ್ರಿಸಬಹುದು",
  "intake.rbiProtectionPostReport": "ಸಂಭಾವ್ಯ ಗ್ರಾಹಕ-ನಿರ್ಲಕ್ಷ್ಯ ಮಾರ್ಗ; ಬ್ಯಾಂಕ್ ಕಾರಣವನ್ನು ಸಾಬೀತುಪಡಿಸಬೇಕು",
  "intake.rbiProtectionNotApplicable": "ಈ ಸುತ್ತೋಲೆಯು ಅನುಮೋದಿತ ಪಾವತಿಯನ್ನು ಒಳಗೊಳ್ಳದಿರಬಹುದು",
  "intake.rbiProtectionUnknown": "ಸುತ್ತೋಲೆಯನ್ನು ಅನ್ವಯಿಸುವ ಮೊದಲು ಹೆಚ್ಚಿನ ಸಂಗತಿಗಳು ಬೇಕಾಗುತ್ತವೆ",
  "intake.evidenceQ": "ಇವುಗಳಲ್ಲಿ ಯಾವುದು ಇನ್ನೂ ನಿಮ್ಮ ಬಳಿಯಿದೆ?",
  "intake.evidenceSub": "ಸುರಕ್ಷಿತವಾಗಿದ್ದರೆ, ಮೂಲ ಚಾಟ್, ವಹಿವಾಟು ದಾಖಲೆ, ಹೆಡರ್‌ಗಳು ಅಥವಾ ಕರೆ ಲಾಗ್ ಅನ್ನು ಸಂರಕ್ಷಿಸಿ. ತುರ್ತು ಸಹಾಯವನ್ನು ವಿಳಂಬ ಮಾಡಬೇಡಿ ಅಥವಾ ಸಾಕ್ಷ್ಯವನ್ನು ಸಂಗ್ರಹಿಸಲು ಮಾತ್ರ ಬೆದರಿಕೆ ಹಾಕುವ ಸಂಪರ್ಕದೊಂದಿಗೆ ತೊಡಗಿಸಿಕೊಳ್ಳುವುದನ್ನು ಮುಂದುವರಿಸಬೇಡಿ. ನೀವು ಮುಂದಿನ ಸ್ಥಳೀಯ ಕೇಸ್ ವಾಲ್ಟ್‌ನಲ್ಲಿ ಫೈಲ್‌ಗಳನ್ನು ಲಗತ್ತಿಸಬಹುದು.",
