  "ev.preserveNote": "ಇದು ಸುರಕ್ಷಿತವಾಗಿದ್ದರೆ, ಸಂಪರ್ಕವನ್ನು ಮುಂದುವರಿಸದೆ ಅಥವಾ ತುರ್ತು ಸಹಾಯವನ್ನು ವಿಳಂಬಗೊಳಿಸದೆ ಮೂಲ ದಾಖಲೆಗಳನ್ನು ಸಂರಕ್ಷಿಸಿ. ಈ ಸ್ಕೋರ್ ನಿಮ್ಮ ಪರಿಶೀಲನಾಪಟ್ಟಿಯನ್ನು ಟ್ರ್ಯಾಕ್ ಮಾಡುತ್ತದೆ; ಇದು ಕಾನೂನುಬದ್ಧ ಸಮರ್ಪಕತೆ ಅಥವಾ ದೃಢೀಕರಣವನ್ನು ನಿರ್ಧರಿಸುವುದಿಲ್ಲ.",
  "ev.recommendedNext": "ಶಿಫಾರಸು ಮಾಡಲಾದ ಮುಂದಿನದು",
  "ev.storageNote": "ಇಲ್ಲಿ ಲಗತ್ತಿಸಲಾದ ಫೈಲ್‌ಗಳನ್ನು ಈ ಬ್ರೌಸರ್‌ನ IndexedDB ನಲ್ಲಿ ನೈಜ ಬೈಟ್‌ಗಳಾಗಿ ಸಂಗ್ರಹಿಸಲಾಗಿದೆ ಮತ್ತು SHA-256 ನೊಂದಿಗೆ ಫಿಂಗರ್‌ಪ್ರಿಂಟ್ ಮಾಡಲಾಗಿದೆ. ಅವುಗಳನ್ನು Kavach ನ ಸರ್ವರ್‌ಗೆ ಅಥವಾ AI ಮಾದರಿಗೆ ಕಳುಹಿಸಲಾಗುವುದಿಲ್ಲ. ಸೈಟ್ ಡೇಟಾವನ್ನು ತೆರವುಗೊಳಿಸುವುದು ಅವುಗಳನ್ನು ಅಳಿಸುತ್ತದೆ; ಮೂಲಗಳನ್ನೂ ಸಹ ಇರಿಸಿ.",
  "ev.manifestTitle": "ಮುದ್ರಿಸಬಹುದಾದ ಸಾಕ್ಷ್ಯ ಮ್ಯಾನಿಫೆಸ್ಟ್",
  "ev.manifestBody": "ನೀವು ಹೊಂದಿರುವ 것, ಕಾಣೆಯಾಗಿರುವ 것, ನಿಮ್ಮ ಕಾಲಾವಧಿ ಮತ್ತು ಲಭ್ಯವಿರುವ ಫಿಂಗರ್‌ಪ್ರಿಂಟ್‌ಗಳ PDF ಪರಿಶೀಲನಾಪಟ್ಟಿಯನ್ನು ರಚಿಸಿ. PDF ಸಾಕ್ಷ್ಯ ಫೈಲ್‌ಗಳನ್ನು ಎಂಬೆಡ್ ಮಾಡುವುದಿಲ್ಲ ಮತ್ತು ಇದು ಅಧಿಕೃತ ದೂರು ಅಲ್ಲ.",
  "ev.generateSummary": "ಸಾಕ್ಷ್ಯ ಸಾರಾಂಶವನ್ನು ರಚಿಸಿ",
  "ev.checklistH2": "ಸಾಕ್ಷ್ಯ ಪರಿಶೀಲನಾಪಟ್ಟಿ",
  "ev.checklistSub": "ಪ್ರತಿ ಐಟಂ ಅದುೇಕೆ ಮುಖ್ಯ ಎಂಬುದನ್ನು ತೋರಿಸುತ್ತದೆ. ಸೇರಿಸಲಾಗಿದೆ, ಕಾಣೆಯಾಗಿದೆ ಅಥವಾ ಅನ್ವಯಿಸುವುದಿಲ್ಲ ಎಂದು ಗುರುತಿಸಿ. PNG, JPG ಅಥವಾ PDF (ಗರಿಷ್ಠ 10 MB) ಲಗತ್ತಿಸಿ.",
