  "ev.block.child": "ಈ ಮಕ್ಕಳ ಸುರಕ್ಷತಾ ಪ್ರಕರಣಕ್ಕೆ ಸ್ಥಳೀಯ ಲಗತ್ತನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ. 18 ವರ್ಷಕ್ಕಿಂತ ಕಡಿಮೆ ವಯಸ್ಸಿನ ಯಾರಿಗಾದರೂ ಸಂಬಂಧಿಸಿದ ಲೈಂಗಿಕ ವಸ್ತುವನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಬೇಡಿ, ಫಾರ್ವರ್ಡ್ ಮಾಡಬೇಡಿ, ಡೌನ್‌ಲೋಡ್ ಮಾಡಬೇಡಿ ಅಥವಾ ಇನ್ನೊಂದು ನಕಲನ್ನು ಮಾಡಬೇಡಿ. ವಸ್ತುವನ್ನು ಮತ್ತೆ ತೆರೆಯದೆ ಮೂಲ ಸಾಧನ, URL ಅಥವಾ ಖಾತೆಯ ವಿವರಗಳನ್ನು ಸಂರಕ್ಷಿಸಿ ಮತ್ತು 1098, 112 ಅಥವಾ ತರಬೇತಿ ಪಡೆದ ರಕ್ಷಣಾ ವೃತ್ತಿಪರರನ್ನು ಸಂಪರ್ಕಿಸಿ.",
  "ev.block.intimate": "Kavach ಮತ್ತೊಂದು ನಕಲನ್ನು ಸೃಷ್ಟಿಸದಂತೆ ಈ ಆಪ್ತ ವಿಷಯದ ಪ್ರಕರಣಕ್ಕೆ ಸ್ಥಳೀಯ ಲಗತ್ತನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ. ವಸ್ತುವನ್ನು ಫಾರ್ವರ್ಡ್ ಮಾಡದೆ ಮೂಲ ಸಾಧನ, URL ಅಥವಾ ಖಾತೆಯ ವಿವರಗಳನ್ನು ಸಂರಕ್ಷಿಸಿ. ನೀವು ಇನ್ನೂ ಐಟಂ ಅನ್ನು ಬೇರೆಡೆ ಇರಿಸಲಾಗಿದೆ ಎಂದು ಗುರುತಿಸಬಹುದು.",
